```javascript
function fib(n) {
  if (!Number.isSafeInteger(n) || n < 0) {
    throw new RangeError("n must be a non-negative safe integer.");
  }

  let previous = 0;
  let current = 1;

  for (let i = 0; i < n; i++) {
    const next = previous + current;
    previous = current;
    current = next;
  }

  return previous;
}
